<x-layouts.public :title="$page->seo_title ?: $page->title" :settings="$settings" :features="$features">
    @php($blocks = $page->blocks ? json_decode($page->blocks, true) : [])
    <article class="public-page-blocks">
        @forelse($blocks as $block)
            @php($data = $block['data'] ?? [])
            @switch($block['type'] ?? '')
                @case('hero')<section class="public-page-hero"><small>{{ $data['eyebrow'] ?? '' }}</small><h1>{{ $data['title'] ?? $page->title }}</h1><p>{{ $data['body'] ?? '' }}</p>@if(!empty($data['button_label']) && !empty($data['button_url']))<a class="button" href="{{ $data['button_url'] }}">{{ $data['button_label'] }}</a>@endif</section>@break
                @case('heading')<section class="public-page-copy"><h2>{{ $data['text'] ?? '' }}</h2></section>@break
                @case('paragraph')<section class="public-page-copy"><p>{!! nl2br(e($data['text'] ?? '')) !!}</p></section>@break
                @case('image')<figure class="public-page-image">@if(!empty($data['url']))<img src="{{ $data['url'] }}" alt="{{ $data['alt'] ?? '' }}">@endif@if(!empty($data['caption']))<figcaption>{{ $data['caption'] }}</figcaption>@endif</figure>@break
                @case('call_to_action')<section class="public-page-callout"><h2>{{ $data['title'] ?? '' }}</h2><p>{{ $data['body'] ?? '' }}</p>@if(!empty($data['button_label']) && !empty($data['button_url']))<a class="button" href="{{ $data['button_url'] }}">{{ $data['button_label'] }}</a>@endif</section>@break
                @case('gallery')@php($galleryImages = array_slice(array_values(array_filter(preg_split('/\R/', (string) ($data['images'] ?? '')) ?: [])), 0, 12))<figure class="public-page-gallery public-gallery-{{ $data['columns'] ?? 'three' }}">@foreach($galleryImages as $image)<img src="{{ trim($image) }}" alt="">@endforeach@if(!empty($data['caption']))<figcaption>{{ $data['caption'] }}</figcaption>@endif</figure>@break
                @case('video_embed')@php($videoUrl = (string) ($data['url'] ?? ''))@php($youtubeId = preg_match('~(?:youtu\.be/|youtube\.com/(?:watch\?v=|embed/|shorts/))([A-Za-z0-9_-]{6,})~', $videoUrl, $match) ? $match[1] : null)@php($vimeoId = preg_match('~vimeo\.com/(?:video/)?([0-9]+)~', $videoUrl, $match) ? $match[1] : null)<figure class="public-page-video">@if($youtubeId)<iframe src="https://www.youtube-nocookie.com/embed/{{ $youtubeId }}" title="{{ $data['title'] ?? 'Video' }}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>@elseif($vimeoId)<iframe src="https://player.vimeo.com/video/{{ $vimeoId }}" title="{{ $data['title'] ?? 'Video' }}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" allow="fullscreen; picture-in-picture" allowfullscreen></iframe>@else<div class="public-page-callout"><strong>Video unavailable</strong><p>Please add a supported YouTube or Vimeo link.</p></div>@endif@if(!empty($data['caption']))<figcaption>{{ $data['caption'] }}</figcaption>@endif</figure>@break
                @case('audio')<figure class="public-page-audio"><figcaption><strong>{{ $data['title'] ?? 'Listen' }}</strong>@if(!empty($data['caption']))<span>{{ $data['caption'] }}</span>@endif</figcaption>@if(!empty($data['url']))<audio controls preload="metadata" src="{{ $data['url'] }}">Your browser does not support audio playback.</audio>@endif</figure>@break
                @case('file')<section class="public-page-file"><div><small>DOWNLOAD</small><h2>{{ $data['label'] ?? 'Download resource' }}</h2><p>{{ $data['description'] ?? '' }}</p></div>@if(!empty($data['url']))<a class="button" href="{{ $data['url'] }}" target="_blank" rel="noopener">Download</a>@endif</section>@break
                @case('media_text')<section class="public-page-media-text public-page-media-{{ $data['placement'] ?? 'left' }}"><div class="public-page-media-visual">@if(!empty($data['media_url']))<img src="{{ $data['media_url'] }}" alt="{{ $data['media_alt'] ?? '' }}">@else<span>Media</span>@endif</div><div><h2>{{ $data['title'] ?? '' }}</h2><p>{{ $data['body'] ?? '' }}</p>@if(!empty($data['button_label']) && !empty($data['button_url']))<a class="button" href="{{ $data['button_url'] }}">{{ $data['button_label'] }}</a>@endif</div></section>@break
                @case('list')<section class="public-page-list"><h2>{{ $data['title'] ?? '' }}</h2>@php($listItems = array_values(array_filter(preg_split('/\R/', (string) ($data['items'] ?? '')) ?: [])))@if(($data['ordered'] ?? 'no') === 'yes')<ol>@foreach($listItems as $item)<li>{{ trim($item) }}</li>@endforeach</ol>@else<ul>@foreach($listItems as $item)<li>{{ trim($item) }}</li>@endforeach</ul>@endif</section>@break
                @case('accordion')<section class="public-page-accordion"><h2>{{ $data['title'] ?? '' }}</h2>@foreach(['one', 'two', 'three'] as $slot)@if(!empty($data['question_'.$slot]))<details><summary>{{ $data['question_'.$slot] }}</summary><p>{{ $data['answer_'.$slot] ?? '' }}</p></details>@endif@endforeach</section>@break
                @case('spacer')<div class="public-page-spacer public-page-spacer-{{ $data['height'] ?? 'medium' }}" aria-hidden="true"></div>@break
                @case('quote')<blockquote class="public-page-quote">“{{ $data['text'] ?? '' }}”@if(!empty($data['attribution']))<small>{{ $data['attribution'] }}</small>@endif</blockquote>@break
                @case('service_times')<section class="public-page-callout"><small>SERVICE TIMES</small><h2>{{ $data['title'] ?? 'Join us this week' }}</h2><p>{{ $data['body'] ?? '' }}</p><a href="{{ route('public.locations') }}">View service times and locations</a></section>@break
                @case('events')<section class="public-page-callout"><small>EVENTS</small><h2>{{ $data['title'] ?? 'What is happening next' }}</h2><p>{{ $data['body'] ?? '' }}</p><a href="{{ route('public.events') }}">Explore events</a></section>@break
                @case('groups')@if(in_array('groups', $features, true))<section class="public-page-callout"><small>GROUPS</small><h2>{{ $data['title'] ?? 'Find your community' }}</h2><p>{{ $data['body'] ?? '' }}</p><a href="{{ route('public.groups') }}">Find a group</a></section>@endif @break
                @case('section')<section class="public-page-section public-page-section-{{ $data['layout'] ?? 'two' }} public-page-section-{{ $data['padding'] ?? 'regular' }}" @if(!empty($data['background_color'])) style="background: {{ $data['background_color'] }}" @endif><header><h2>{{ $data['title'] ?? '' }}</h2><p>{{ $data['body'] ?? '' }}</p></header><div class="public-page-columns"><div><h3>{{ $data['column_one_title'] ?? '' }}</h3><p>{{ $data['column_one_body'] ?? '' }}</p></div>@if(($data['layout'] ?? 'two') !== 'one')<div><h3>{{ $data['column_two_title'] ?? '' }}</h3><p>{{ $data['column_two_body'] ?? '' }}</p></div>@endif@if(($data['layout'] ?? '') === 'three')<div><h3>{{ $data['column_three_title'] ?? '' }}</h3><p>{{ $data['column_three_body'] ?? '' }}</p></div>@endif</div></section>@break
                @case('divider')<hr class="public-page-divider">@break
            @endswitch
        @empty
            <header class="public-heading"><p>ABOUT THIS MINISTRY</p><h1>{{ $page->title }}</h1></header><div class="prose">{!! nl2br(e($page->body)) !!}</div>
        @endforelse
    </article>
</x-layouts.public>
